// FLAKE-3 fix 5 (W1)
func TestFixtureStopFailureMessages(t *testing.T) { // FLAKE-3 fix 5 (W1)
	for _, message := range []string{"fixture PostgreSQL shutdown timeout", "fixture process creation identity mismatch", "fixture process identity mismatch"} { // FLAKE-3 fix 5 (W1)
		t.Run(message, func(t *testing.T) { // FLAKE-3 fix 5 (W1)
			got, code := fixtureStopFailure(errors.New(message)) // FLAKE-3 fix 5 (W1)
			if got != message || code != 1 {                     // FLAKE-3 fix 5 (W1)
				t.Fatal("stop message classification differs") // FLAKE-3 fix 5 (W1)
			} // FLAKE-3 fix 5 (W1)
			got, code = fixtureStopFailure(errors.New("synthetic private path " + message)) // FLAKE-3 fix 5 (W1)
			if got != "synthetic lifecycle fixture failed" || code != 1 {                   // FLAKE-3 fix 5 (W1)
				t.Fatal("private stop detail was not redacted") // FLAKE-3 fix 5 (W1)
			} // FLAKE-3 fix 5 (W1)
		}) // FLAKE-3 fix 5 (W1)
	} // FLAKE-3 fix 5 (W1)
	message, code := fixtureStopFailure(errors.New("unknown synthetic failure")) // FLAKE-3 fix 5 (W1)
	if message != "synthetic lifecycle fixture failed" || code != 1 {            // FLAKE-3 fix 5 (W1)
		t.Fatal("unknown stop detail was not redacted") // FLAKE-3 fix 5 (W1)
	} // FLAKE-3 fix 5 (W1)
} // FLAKE-3 fix 5 (W1)
// FLAKE-3 fix 5 (W1)
func TestFixtureStopFailureHelperExit(t *testing.T) { // FLAKE-3 fix 5 (W1)
	if len(os.Args) > 2 && os.Args[len(os.Args)-2] == "--fixture-diagnostic-exit" { // FLAKE-3 fix 5 (W1)
		code, err := strconv.Atoi(os.Args[len(os.Args)-1]) // FLAKE-3 fix 5 (W1)
		if err != nil {                                    // FLAKE-3 fix 5 (W1)
			os.Exit(127) // FLAKE-3 fix 5 (W1)
		} // FLAKE-3 fix 5 (W1)
		os.Exit(code) // FLAKE-3 fix 5 (W1)
	} // FLAKE-3 fix 5 (W1)
	for _, code := range []int{124, 125, 126} { // FLAKE-3 fix 5 (W1)
		t.Run(strconv.Itoa(code), func(t *testing.T) { // FLAKE-3 fix 5 (W1)
			command := exec.Command(os.Args[0], "-test.run=^TestFixtureStopFailureHelperExit$", "--", "--fixture-diagnostic-exit", strconv.Itoa(code)) // FLAKE-3 fix 5 (W1)
			err := command.Run()                                                                                                                       // FLAKE-3 fix 5 (W1)
			if err == nil {                                                                                                                            // FLAKE-3 fix 5 (W1)
				t.Fatal("helper probe unexpectedly succeeded") // FLAKE-3 fix 5 (W1)
			} // FLAKE-3 fix 5 (W1)
			expected := code // FLAKE-3 fix 5 (W1)
			if code == 126 { // FLAKE-3 fix 5 (W1)
				expected = 1 // FLAKE-3 fix 5 (W1)
			} // FLAKE-3 fix 5 (W1)
			message, actual := fixtureStopFailure(fmt.Errorf("synthetic private helper detail %w", err)) // FLAKE-3 fix 5 (W1)
			if message != "synthetic lifecycle fixture failed" || actual != expected {                   // FLAKE-3 fix 5 (W1)
				t.Fatal("helper exit classification differs") // FLAKE-3 fix 5 (W1)
			} // FLAKE-3 fix 5 (W1)
		}) // FLAKE-3 fix 5 (W1)
	} // FLAKE-3 fix 5 (W1)
} // FLAKE-3 fix 5 (W1)
